public static int[][] pascal(int n) {
    int[][] tri = new int[n][];
    for (int i = 0; i < n; i++) {
        tri[i] = new int[i + 1];
        tri[i][0] = 1;
        tri[i][i] = 1;
        for (int j = 1; j < i; j++) {
            tri[i][j] = tri[i - 1][j - 1] + tri[i - 1][j];
        }
    }
    return tri;
}
